obj _NumberFormatter {
    has locale: str;
    has compact: bool = False;

    def format(value: float) -> str {
        if self.compact {
            abs_val = abs(value);
            if abs_val >= 1_000_000_000 {
                scaled = value / 1_000_000_000;
                suffix = "mil millones" if self.locale.startswith("es") else "billion";
                return f"{scaled:.1f} {suffix}";
            }
            if abs_val >= 1_000_000 {
                scaled = value / 1_000_000;
                suffix = "millones" if self.locale.startswith("es") else "million";
                return f"{scaled:.1f} {suffix}";
            }
            if abs_val >= 1_000 {
                scaled = value / 1_000;
                suffix = "mil" if self.locale.startswith("es") else "thousand";
                return f"{scaled:.1f} {suffix}";
            }
        }
        if value == int(value) {
            return f"{int(value):,}";
        }
        return f"{value:,.2f}";
    }
}

glob _numberFormatters: dict[str, _NumberFormatter] = {};
glob _compactFormatters: dict[str, _NumberFormatter] = {};

def getNumberFormatter(locale_name: str) -> _NumberFormatter {
    cached = _numberFormatters.get(locale_name);

    if cached is not None {
        return cached;
    }
    formatter = _NumberFormatter(locale=locale_name, compact=False);
    _numberFormatters[locale_name] = formatter;
    return formatter;
}

