type VerifyErrorCode = Literal["empty_key", "invalid_key", "network_error", "unknown_provider", "request_failed"];

obj VerifyResult {
    has success: bool;
    has errorCode: VerifyErrorCode | None = None;
    has errorDetail: str | None = None;
    has availableModelIds: list[str] | None = None;
}

async def verifyApiKey(providerId: AIProviderId, apiKey: str, apiUrl: str | None = None) -> VerifyResult {
    if not apiKey.strip() {
        return VerifyResult(success=False, errorCode="empty_key");
    }
    preset = AI_PROVIDER_PRESETS.get(providerId);
    if preset is None {
        return VerifyResult(success=False, errorCode="unknown_provider");
    }
    baseUrl = apiUrl or preset["defaultApiUrl"];
    endpoint = preset.get("modelsEndpoint") or "/v1/models";
    url = f"{baseUrl}{endpoint}";
    def do_get() -> tuple[int, object | None] {
        req = urllib.request.Request(url, headers={"Authorization": f"Bearer {apiKey}"});
        try {
            resp = urllib.request.urlopen(req);
            body = resp.read();
            parsed = json.loads(body);
            status = resp.status;
            resp.close();
            return (status, parsed);
        } except urllib.error.HTTPError as e {
            return (e.code, None);
        } except urllib.error.URLError {
            return (-1, None);
        }
    }
    try {
        (status, json_data) = await asyncio.to_thread(do_get);
        if status == -1 {
            return VerifyResult(success=False, errorCode="network_error");
        }
        if status == 200 and json_data is not None {
            ids = extractModelIds(json_data);
            return VerifyResult(success=True, availableModelIds=ids);
        }
        if status == 401 {
            return VerifyResult(success=False, errorCode="invalid_key");
        }
        return VerifyResult(success=False, errorCode="request_failed", errorDetail=str(status));
    } except Exception {
        return VerifyResult(success=False, errorCode="network_error");
    }
}

def extractModelIds(data: object) -> list[str] {

    if not isinstance(data, dict) {
        return [];
    }
    raw_data = data.get("data");
    if not isinstance(raw_data, list) {
        return [];
    }
    ids: list[str] = [];
    for m in raw_data {
        if isinstance(m, dict) and isinstance(m.get("id"), str) {
            ids.append(m["id"]);
        }
    }
    return ids;
}

