import re;

obj TimeValidationResult {
    has isValid: bool = False;
    has hours: int = 0;
    has minutes: int = 0;
    has seconds: int = 0;
}

def humanTimeValidation(input: str) -> TimeValidationResult {
    result = TimeValidationResult(isValid=False, hours=0, minutes=0, seconds=0);
    if not input {
        return result;
    }
    input = input.strip();
    has_colon = ":" in input;
    has_dot = "." in input;
    if has_colon and has_dot {
        return result;
    }
    if not has_colon and not has_dot {
        return result;
    }
    separator = ":" if has_colon else ".";
    parts = input.split(separator);
    if len(parts) < 2 or len(parts) > 3 {
        return result;
    }
    h = parts[0];
    m = parts[1];
    s = parts[2] if len(parts) > 2 else "0";
    if not all(re.match(r"^\d+$", x) for x in [h, m, s]) {
        return result;
    }
    hours = int(h);
    minutes = int(m);
    seconds = int(s);
    if minutes < 0 or minutes > 59 {
        return result;
    }
    if seconds < 0 or seconds > 59 {
        return result;
    }
    if hours < 0 {
        return result;
    }
    return TimeValidationResult(isValid=True, hours=hours, minutes=minutes, seconds=seconds);
}

obj DateInputParse {
    has dateTime: str;
    has utcOffset: str | None = None;
}

def parseDateInput(input: str) -> DateInputParse {

    trimmed = input.strip();
    match_obj = re.match(r"^(.+?)\s*([+-]\d{2}:\d{2}|Z)$", trimmed);
    if match_obj is None {
        return DateInputParse(dateTime=trimmed, utcOffset=None);
    }
    return DateInputParse(dateTime=match_obj.group(1).strip(), utcOffset=match_obj.group(2));
}

