""" Extract tokens from command arguments """
def get_command_tokens(arguments: list[list | dict[str, str | list]] | dict[str, str | list[list | dict[str, str | list]]]) -> set[str] {
    rep = set();
    if type(arguments) is list {
        for arg in arguments {
            rep = rep.union(get_command_tokens(arg));
        }
    } else {

        if 'token' in arguments {
            rep.add(arguments['token']);
        }
        if 'arguments' in arguments {
            args = arguments['arguments'] as list[list | dict[str, str | list]];
            for arg in args {
                rep = rep.union(get_command_tokens(arg));
            }
        }
    }
    return rep;
}

