import re;

obj SearchableItem {
    has id: str;
    has title: str;
    has content: str;
    has tags: list[str] = [];
}

glob invertedIndex: dict[str, set[str]] = {};

def tokenize(text: str) -> list[str] {
    cleaned = re.sub(r'[^\w\s]', ' ', text.lower());
    parts: list[str] = re.split(r'\s+', cleaned);
    return [t for t in parts if len(t) > 1];
}

def buildIndex(items: list[SearchableItem]) {
    invertedIndex.clear();
    for item in items {
        textParts: list[str] = [item.title, item.content];
        if item.tags and len(item.tags) > 0 {
            textParts.append(" ".join(item.tags));
        }
        tokens = tokenize(" ".join(textParts));
        uniqueTokens = set(tokens);
        for token in uniqueTokens {
            if token not in invertedIndex {
                invertedIndex[token] = set();
            }
            invertedIndex[token].add(item.id);
        }
    }
}

def search(query: str, limit: int = 50) -> list[str] {
    queryTokens = tokenize(query);
    if len(queryTokens) == 0 {
        return [];
    }
    indexTokens = list(invertedIndex.keys());
    scores: dict[str, int] = {};
    for qToken in queryTokens {
        matched: set[str] = set();
        exactPostings = invertedIndex.get(qToken);
        if exactPostings {
            for itemId in exactPostings {
                matched.add(itemId);
            }
        }
        if len(qToken) >= 3 {
            for token in indexTokens {

                if token.startswith(qToken) {
                    prefixPostings = invertedIndex.get(token);
                    if prefixPostings {
                        for itemId in prefixPostings {
                            matched.add(itemId);
                        }
                    }
                }
            }
        }
        for itemId in matched {
            scores[itemId] = scores.get(itemId, 0) + 1;
        }
    }
    ranked = sorted(
        scores.keys(),
        key=lambda (itemId: str) -> int { return scores[itemId]; },
        reverse=True
    );
    return ranked[0:limit];
}

