        self.fieldName = fieldName;
    }

    def get_values() -> list[float] {
        return self._values;
    }

    def get_minValue() -> float {
        return self._minValue;
    }

    def get_maxValue() -> float {
        return self._maxValue;
    }

    def get_isApplied() -> bool {
        return self.range[0] != self._minValue or self.range[1] != self._maxValue;
    }

    def apply() {
        self._onChanged();
    }

    def reset() {
        self.range = [self._minValue, self._maxValue];
        self._onChanged();
    }

    def populateFacetValues(facetValues: list[dict[str, float]], filterClause: str) {
        self._values = [fv["value"] for fv in facetValues];
        self._minValue = min(self._values);
        self._maxValue = max(self._values);
        numericRange = self.parseFilterExpression(filterClause);
        if not numericRange {
            numericRange = [self._minValue, self._maxValue];
        }
        self.range = numericRange;
    }

    def updateFacetValueCounts(facetValues: list[dict[str, float]]) {
    }

    def getFilterExpression() -> str {
        if not self.get_isApplied() {
            return "";
        }
        return f"{self.fieldName} ge {self.range[0]} and {self.fieldName} le {self.range[1]}";
    }

    def parseFilterExpression(filterClause: str) -> Optional[list[float]] {

    if not filterClause {
        return None;
    }
    pattern = f"{self.fieldName} ge ([0-9.]+) and {self.fieldName} le ([0-9.]+)";
    regexMatch = re.search(pattern, filterClause);
    if not regexMatch {
        return None;
    }
    return [float(regexMatch.group(1)), float(regexMatch.group(2))];
}

