"""Comment moderation: immutable original body, append-only moderation history,
delete/restore transitions with role hierarchy and conflict detection.

Models the essential pieces of issue #317 as a graph:
  - Comment nodes carry the immutable original body, author, and current
    deletion state (derived from the moderation history).
  - ModerationEvent nodes are append-only; each records actor, action,
    timestamp, and reason (for deletes).
  - Author nodes declare a role (User / Admin / SuperAdmin) so role
    hierarchy is part of the graph.
  - Typed edges carry meaning: Authored, RepliedTo, Moderated.
A Moderator walker walks the moderation history of a comment to derive the
current state, enforce role hierarchy, and detect stale-version conflicts.
"""

# ---------- edge archetypes ----------
edge Authored { }
edge RepliedTo { }
edge Moderated { }

# ---------- node archetypes ----------
node Author {
    has display_name: str = "";
    has role: str = "User";  # "User" | "Admin" | "SuperAdmin"
}

node Comment {
    has body: str = "";          # IMMUTABLE original body
    has created_at: str = "";
    has is_deleted: bool = False; # projected from history
}

node ModerationEvent {
    has action: str = "";        # "delete" | "restore"
    has actor: str = "";
    has actor_role: str = "";
    has reason: str = "";        # required for delete; empty for restore
    has ts: str = "";
    has expected_version: int = 0;
}

# ---------- walker ----------
walker AuditTrail {
    has comment_body: str = "";
    has current_state: str = "active";
    has version: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan with Comment entry {
        # Snapshot the immutable original body so a downstream caller
        # could (in an authorized admin context) return it.
        self.comment_body = here.body;
        visit [->:Moderated:->];
    }

    can record with ModerationEvent entry {
        # Walk history in graph order, last-write-wins projected state.
        self.version += 1;
        if here.action == "delete" {
            self.current_state = "deleted";
        } elif here.action == "restore" {
            self.current_state = "active";
        }
        visit [->:Moderated:->];
    }
}

walker Moderator {
    has actor_name: str = "admin1";
    has actor_role: str = "Admin";
    has action: str = "delete";        # "delete" | "restore"
    has reason: str = "";
    has expected_version: int = -1;
    has conflict: str = "";
    has applied: bool = False;
    has target_author_role: str = "User";

    # Role hierarchy: cannot moderate equal-or-higher effective role.
    def role_allowed(actor_role: str, target_role: str) -> bool {
        if actor_role == "SuperAdmin" {
            return True;
        }

    if actor_role == "Admin" and target_role == "User" {
        return True;
    }
    return False;
}

