def getObservableSibling(element: DomEl) -> DomEl | None {
    nextSibling = element.nextElementSibling;
    if not nextSibling {
        return None;
    }
    nextSiblingStyle: CssComputed = getComputedStyle(nextSibling) as CssComputed;
    if nextSiblingStyle.display != "none" {
        return nextSibling;
    }
    return getObservableSibling(nextSibling);
}

def getObservableElement(element: DomEl) -> DomEl | None {
    observableSibling = getObservableSibling(element);
    if observableSibling {
        return observableSibling;
    }
    parentElement = element.parentElement;
    if not parentElement {
        return None;
    }
    return getObservableElement(parentElement);
