"""Worktree adoption archive: model the destructive parent-directory removal bug.

Entities:
  - Repo: a main git repository (e.g. ~/code/<parent>/<repo>).
  - Worktree: a checkout of a Repo. May be *internal* (lives under the app's
    private directory and is safe to remove alongside its parent) or
    *adopted* (lives outside the app, sharing its parent directory with the
    Repo and with unrelated siblings; its parent must NOT be removed).
  - Sibling: an unrelated filesystem entry that shares the parent with an
    adopted worktree (e.g. another repo or a sentinel file).

Edges (typed, carry meaning):
  - HasWorktree: Repo -> Worktree (the main repo owns this checkout).
  - SharesParent: any node -> another node that lives in the same parent
    directory. Lets the walker enumerate what would be nuked if the parent
    were force-removed.

Walker:
  - Archiver: traverses the graph the way the buggy ArchiveService did.
    For an *internal* worktree it is safe (and correct) to remove the
    parent directory; for an *adopted* worktree it MUST stop before
    touching the parent and report the would-be collateral damage so the
    caller can refuse the operation. This is the cycle/blast-radius guard
    the shipped code was missing.
"""

node Repo {
    has name: str = "";
    has parent_dir: str = "";
}

node Worktree {
    has branch: str = "";
    has path: str = "";
    has adopted: bool = False;
    has task_id: str = "";
}

node Sibling {
    has label: str = "";
}

edge HasWorktree {
    has since: str = "";
}

edge SharesParent {
    has parent_dir: str = "";
}

walker Archiver {
    has target_task: str = "";
    has collateral: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        # Find the worktree that matches the task the user archived.
        visit [-->];
    }

    can locate with Worktree entry {
        if here.task_id == self.target_task {
            if here.adopted {
                self._audit_adopted(here);
            } else {
                self._safe_archive(here);
            }
            disengage;
        }
        visit [-->];
    }

    # Helper: an adopted worktree's parent directory must NOT be removed.
    # Walk every node that SharesParent with the adopted checkout (the main
    # repo, every sibling worktree, every unrelated entry) and refuse.
    def _audit_adopted(wt: Worktree) -> None {
        parent_label = wt.path.rsplit("/", 1)[0] if "/" in wt.path else wt.path;
        print(f"[adopted] {wt.path} shares parent {parent_label}");
        print("  refusing to remove parent: would destroy:");

    # Typed-edge traversal: enumerate every node sharing the parent.
    seen: list[str] = [];
    self._collect_labels(wt, seen);

    for label in seen {
        self.collateral.append(label);
        print(f"    - {label}");
    }
    self.blocked = True;
    print("[blocked] archive refused: parent directory is shared");
}

