import from "react" { useEffect, useRef }

def:pub FloatingParticles() -> JsxElement {
    canvasRef = useRef(None);

    useEffect(lambda () -> Callable[[], None] {
        canvas = canvasRef.current;
        if not canvas {
            return lambda () -> None {};
        }
        ctx = canvas.getContext("2d");
        if not ctx {
            return lambda () -> None {};
        }

        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;

        particles: list[dict[str, float]] = [];
        for _ in range(50) {
            particles.append({
                "x": Math.random() * canvas.width,
                "y": Math.random() * canvas.height,
                "size": Math.random() * 3 + 1,
                "speedX": (Math.random() - 0.5) * 0.5,
                "speedY": (Math.random() - 0.5) * 0.5,
                "opacity": Math.random() * 0.5 + 0.2,
            });
        }

        def animate() -> None {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            for particle in particles {
                ctx.beginPath();
                ctx.arc(particle["x"], particle["y"], particle["size"], 0, Math.PI * 2);

                ctx.fillStyle = f"rgba(147, 51, 234, {particle['opacity']})";
                ctx.fill();
                particle["x"] += particle["speedX"];
                particle["y"] += particle["speedY"];
                if particle["x"] < 0 or particle["x"] > canvas.width {
                    particle["speedX"] *= -1;
                }
                if particle["y"] < 0 or particle["y"] > canvas.height {
                    particle["speedY"] *= -1;
                }
            }
            requestAnimationFrame(animate);
        }

        animate();

        def handleResize() -> None {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        }

        window.addEventListener("resize", handleResize);
        return lambda () -> None {
            window.removeEventListener("resize", handleResize);
        };
    }, []);

    <canvas ref={canvasRef} className="pointer-events-none absolute inset-0 opacity-30" />
}

