    def __call__(ctx: dict[str, object]) -> bool | None {
        try {
            evalFn = getattr(self.parsedNode, "eval");
            return bool(evalFn(ctx));
        } except Exception as e {
            LOG.warnOnce(f"Runtime error in when-clause \"{self.clause}\":", e);
        }
    }
}

obj WhenClauseCompiler {
    has cache: dict[str, When] = {};

    def compile(whenClause: str | None) -> When | None {
        if not whenClause {
            return None;
        }
        cachedWhenFn = self.cache.get(whenClause);
        if cachedWhenFn {
            return cachedWhenFn;

    }
    parsedNode = Parser.parse(whenClause, {"evalMissingNameTo": "name"});
    whenFn = CompiledWhen(clause=whenClause, parsedNode=parsedNode) as When;
    self.cache[whenClause] = whenFn;
    return whenFn;
}

